<script>
(() => {
  'use strict';
  const PROTOCOL_VERSION = '1';
  const LOG = '[航站终端]';
  const DEBUG = false;
  const subscriptions = [];
  let messageId = null;
  let swipeId = null;

  function debug(...args) { if (DEBUG) console.log(LOG, ...args); }
  function warn(...args) { console.warn(LOG, ...args); }

  function text(value, fallback, max) {
    if (typeof value !== 'string') return fallback;
    const normalized = value.trim();
    return normalized ? normalized.slice(0, max) : fallback;
  }

  function normalizePayload(value) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('载荷根必须是 JSON object');
    const missing = [];
    const required = (key, max) => {
      const result = text(value[key], '', max);
      if (!result) missing.push(key);
      return result || '未记录';
    };
    const actions = [];
    let dropped = 0;
    if (Array.isArray(value.行动)) {
      for (const item of value.行动) {
        if (actions.length >= 8) { dropped += 1; continue; }
        if (!item || typeof item !== 'object' || Array.isArray(item)) { dropped += 1; continue; }
        const label = text(item.label, '', 32);
        const actionText = text(item.text, '', 220);
        if (!label || !actionText) { dropped += 1; continue; }
        actions.push({ label, text: actionText });
      }
    } else if (value.行动 != null) {
      dropped += 1;
    }
    return {
      version: PROTOCOL_VERSION,
      area: required('区域', 80),
      weather: required('天气', 80),
      task: required('任务', 160),
      notice: text(value.提示, '', 400),
      actions,
      missing,
      dropped,
    };
  }

  function extractPayload(messageText) {
    const input = String(messageText ?? '');
    const re = /<航站状态\s+v="([^"]+)">([\s\S]*?)<\/航站状态>/g;
    let match;
    let last = null;
    while ((match = re.exec(input)) !== null) last = { version: match[1], json: match[2].trim() };
    if (!last) throw new Error('当前楼层缺少完整航站状态载荷');
    if (last.version !== PROTOCOL_VERSION) throw new Error(`不支持的载荷版本：${last.version}`);
    let parsed;
    try { parsed = JSON.parse(last.json); }
    catch (error) { throw new Error(`JSON 解析失败：${error.message}`); }
    return normalizePayload(parsed);
  }

  const testHook = globalThis.__TH_PAYLOAD_TEST__;
  if (testHook && typeof testHook.register === 'function') {
    testHook.register({ extractPayload, normalizePayload, protocolVersion: PROTOCOL_VERSION });
    if (testHook.skipBoot) return;
  }

  const q = id => document.getElementById(id);

  function setStatus(message, tone = '') {
    q('status').className = `status ${tone}`.trim();
    q('status').textContent = message;
  }

  function renderActions(actions) {
    const root = q('actions');
    root.replaceChildren();
    if (!actions.length) {
      const empty = document.createElement('div');
      empty.className = 'empty';
      empty.textContent = '当前快照没有建议行动；仍可在输入框自由回复。';
      root.appendChild(empty);
      return;
    }
    actions.forEach(item => {
      const button = document.createElement('button');
      button.type = 'button';
      button.textContent = item.label;
      button.dataset.actionText = item.text;
      button.setAttribute('aria-label', `写入输入框：${item.label}`);
      root.appendChild(button);
    });
  }

  function render(data) {
    q('area').textContent = data.area;
    q('weather').textContent = data.weather;
    q('task').textContent = data.task;
    q('notice').hidden = !data.notice;
    q('noticeText').textContent = data.notice;
    renderActions(data.actions);
    q('identity').textContent = `第 ${messageId} 楼 · Swipe ${swipeId} · 协议 v${data.version}`;
    q('retry').classList.remove('on');
    if (data.missing.length) {
      setStatus(`数据不完整：缺少 ${data.missing.join('、')}。未沿用其他楼层的旧值。`, 'warn');
    } else if (data.dropped) {
      setStatus(`读取成功；已忽略 ${data.dropped} 条非法或超量行动。`, 'warn');
    } else {
      setStatus('读取成功；本面板只表示当前消息快照。', 'ok');
    }
  }

  async function refresh() {
    try {
      if (typeof getCurrentMessageId !== 'function' || typeof getChatMessages !== 'function') throw new Error('当前不是 Tavern Helper 消息 iframe');
      const id = Number(getCurrentMessageId());
      if (!Number.isInteger(id) || id < 0) throw new Error('无法取得数值消息楼层');
      const message = getChatMessages(id, { include_swipes: true })[0];
      if (!message) throw new Error(`无法读取第 ${id} 楼`);
      messageId = id;
      const currentSwipe = Number(message.swipe_id ?? 0);
      swipeId = Number.isInteger(currentSwipe) && currentSwipe >= 0 ? currentSwipe : 0;
      debug('read', { message_id: messageId, swipe_id: swipeId, version: PROTOCOL_VERSION });
      render(extractPayload(message.message));
    } catch (error) {
      warn('refresh failed', error);
      q('area').textContent = q('weather').textContent = q('task').textContent = '不可用';
      q('notice').hidden = true;
      renderActions([]);
      q('identity').textContent = messageId == null ? '宿主不可用' : `第 ${messageId} 楼 · Swipe ${swipeId ?? '未知'}`;
      setStatus(`读取失败：${error.message}`, 'bad');
      q('retry').classList.add('on');
    }
  }

  async function writeAction(button) {
    const actionText = String(button.dataset.actionText || '');
    if (!actionText) return;
    const bridge = window.航站输入桥 || window.parent?.航站输入桥;
    button.disabled = true;
    try {
      if (!bridge || typeof bridge.setInput !== 'function') throw new Error('输入桥未启用');
      await bridge.setInput(actionText);
      setStatus('行动已写入输入框；可以继续编辑，尚未发送。', 'ok');
    } catch (error) {
      setStatus(`${error.message}；请手动复制：${actionText}`, 'bad');
    } finally {
      button.disabled = false;
    }
  }

  q('actions').addEventListener('click', event => {
    const button = event.target.closest('button[data-action-text]');
    if (button) writeAction(button);
  });
  q('retry').addEventListener('click', refresh);

  if (typeof eventOn === 'function' && typeof tavern_events === 'object') {
    for (const eventName of [tavern_events.MESSAGE_UPDATED, tavern_events.MESSAGE_SWIPED]) {
      if (!eventName) continue;
      subscriptions.push(eventOn(eventName, id => {
        if (Number(id) === messageId) refresh();
      }));
    }
  }

  addEventListener('pagehide', () => {
    subscriptions.forEach(item => item?.stop?.());
    debug('pagehide cleanup', { message_id: messageId, swipe_id: swipeId });
  }, { once: true });

  refresh();
})();
</script>
